export const ComputerController = () => {
  // NOTE: Generated by codex...
  // Justification: Did not want to manually write every index and could not think of a faster way to generate the possibleIndexes.
  const possibleIndexes = Array.from({ length: 100 }, (_, index) => [
    Math.floor(index / 10),
    index % 10,
  ]);

  const attackRandomCoordinate = (enemyBoard) => {
    const length = possibleIndexes.length;
    const randomIndex = Math.floor(Math.random() * (length + 1));
    const randomCoordinate = possibleIndexes[randomIndex];

    return enemyBoard.receiveAttack(randomCoordinate);
  };

  return {
    attackRandomCoordinate,
  };
};
